/**
 * Preview cache — small on-disk cache for preview clips (transitions,
 * animations, effects). Keyed by a caller-supplied stable string; the cache
 * hashes it to a flat filename so paths stay short across OSes.
 *
 * Why a file cache: previews are regenerated by FFmpeg and cost ~300ms
 * each. Re-rendering on every hover would make the picker unusably slow.
 * Why bounded by count rather than bytes: preview clips are small (~40-80KB)
 * and roughly uniform in size — a count-based LRU is simpler and good enough.
 */

import fs from 'fs'
import path from 'path'
import crypto from 'crypto'
import { createRequire } from 'module'
import { assertWriteIsolatedInTests } from '../lib/test-isolation.js'

const require = createRequire(import.meta.url)

const MAX_ENTRIES = 200

/**
 * The cache-root directory, resolved on EVERY access.
 *
 * Deliberately not captured in a module-scope variable, even a lazily-set
 * one. `STORY_STUDIO_DATA_DIR` is what redirects this cache into an isolated
 * directory, and it is set by the caller — the Electron main process at boot,
 * `useTempDataDir()` in tests. Memoising on first CALL still froze the path:
 * whichever test happened to call `cachePath`/`getOrRender` first — in any
 * file sharing this test worker process — bound the root for every later
 * test, including ones that had already claimed their own temp dir. Same
 * shape as `services/app-settings.ts`. Directory creation is deferred to the
 * actual write sites below (`getOrRender`), not done here, so a plain read
 * (`cachePath` used to check a cache hit) never side-effects the filesystem.
 */
function resolveCacheRoot(): string {
  if (process.env.STORY_STUDIO_DATA_DIR) {
    return path.join(process.env.STORY_STUDIO_DATA_DIR, 'preview-cache')
  }
  try {
    const { app } = require('electron')
    if (app && typeof app.getPath === 'function') {
      return path.join(app.getPath('userData'), 'preview-cache')
    }
  } catch { /* not in Electron */ }
  return path.join(process.cwd(), '.preview-cache')
}

function hashKey(key: string): string {
  return crypto.createHash('sha1').update(key).digest('hex').slice(0, 20)
}

export function cachePath(key: string, ext: string): string {
  const ensuredExt = ext.startsWith('.') ? ext : `.${ext}`
  return path.join(resolveCacheRoot(), `${hashKey(key)}${ensuredExt}`)
}

/**
 * Return the cached path if present; otherwise invoke `render(targetPath)`
 * and return the produced path. `render` must write to `targetPath` — the
 * cache confirms the file exists and is non-empty before returning.
 */
// ── Render concurrency gate (v1.0.515) ──────────────────────────────────
// The preview pickers fire several renders at once (the animation strip
// requested 5 simultaneously), each an ffmpeg spawn. Unbounded, they compete
// with real render jobs for CPU — and on 2026-07-05 five of them wedged
// side-by-side for 30+ minutes. Cap concurrent preview renders at 2; extra
// requests queue here (cache hits above skip the gate entirely). Also
// dedupes: concurrent requests for the SAME key await one render instead of
// racing to write the same target file.
const MAX_CONCURRENT_RENDERS = 2
let activeRenders = 0
const renderWaiters: Array<() => void> = []
const inFlightByTarget = new Map<string, Promise<void>>()

async function acquireRenderSlot(): Promise<void> {
  if (activeRenders < MAX_CONCURRENT_RENDERS) { activeRenders++; return }
  await new Promise<void>(resolve => renderWaiters.push(resolve))
  activeRenders++
}
function releaseRenderSlot(): void {
  activeRenders--
  renderWaiters.shift()?.()
}

export async function getOrRender(
  key: string,
  ext: string,
  render: (targetPath: string) => Promise<void>,
): Promise<string> {
  const target = cachePath(key, ext)
  try {
    const stat = fs.statSync(target)
    if (stat.isFile() && stat.size > 0) {
      // Touch mtime so LRU eviction sees this as recent.
      const now = Date.now()
      fs.utimesSync(target, now / 1000, now / 1000)
      return target
    }
  } catch { /* not cached yet */ }

  // Same-key dedupe: piggyback on an in-flight render of this exact target.
  const existing = inFlightByTarget.get(target)
  if (existing) {
    await existing
  } else {
    const p = (async () => {
      await acquireRenderSlot()
      try {
        // Under the node test runner, a render whose target falls outside the
        // claimed temp data dir is a hard error, not a silent write to the
        // developer's real cache directory. See lib/test-isolation.ts.
        assertWriteIsolatedInTests(target, 'preview-cache')
        fs.mkdirSync(path.dirname(target), { recursive: true })
        await render(target)
      } finally {
        releaseRenderSlot()
      }
    })()
    inFlightByTarget.set(target, p)
    try {
      await p
    } finally {
      inFlightByTarget.delete(target)
    }
  }

  const stat = fs.statSync(target)
  if (!stat.isFile() || stat.size === 0) {
    throw new Error(`preview render produced no output at ${target}`)
  }

  evictIfOverflowing().catch(() => { /* best effort */ })
  return target
}

async function evictIfOverflowing(): Promise<void> {
  const root = resolveCacheRoot()
  assertWriteIsolatedInTests(root, 'preview-cache')
  let entries: { file: string; mtime: number }[]
  try {
    const files = await fs.promises.readdir(root)
    entries = await Promise.all(files.map(async (file) => {
      const stat = await fs.promises.stat(path.join(root, file))
      return { file, mtime: stat.mtimeMs }
    }))
  } catch { return }
  if (entries.length <= MAX_ENTRIES) return
  entries.sort((a, b) => a.mtime - b.mtime)
  const toRemove = entries.length - MAX_ENTRIES
  await Promise.all(entries.slice(0, toRemove).map(e =>
    fs.promises.unlink(path.join(root, e.file)).catch(() => {})
  ))
}

/** Manual invalidation (future-proof — unused today). */
export function invalidate(key: string, ext: string): void {
  const target = cachePath(key, ext)
  assertWriteIsolatedInTests(target, 'preview-cache')
  try { fs.unlinkSync(target) } catch {}
}
